def frame():
    homepage = (ROOT / 'index.html').read_text(encoding='utf-8')
    header = re.search(r'<header class="topbar shared-header">.*?</header>', homepage, re.S).group(0)
    header = header.replace('href="#', 'href="/#')
    footer = re.search(r'<footer class="shared-footer">.*?</footer>', homepage, re.S).group(0)
    tawk = re.search(r'<!--Start of Tawk.to Script-->.*?<!--End of Tawk.to Script-->', homepage, re.S).group(0)
    return header, footer, tawk


def render(path, title, description, h1, intro, body, kind='service', facts=None, scripts=()):
    header, footer, tawk = frame()
    url = BASE + path
    entity_type = 'Service' if kind == 'service' else 'Article' if kind == 'guide' else 'WebApplication' if kind == 'tool' else 'CollectionPage'
    entity = {'@type': entity_type, '@id': url + '#entity', 'name': h1, 'url': url, 'description': description}
    if kind == 'service':
        entity.update(provider={'@type': 'Person', '@id': BASE + '/#person', 'name': 'Hasnain Qureshi'}, areaServed=[{'@type': 'Country', 'name': 'United Kingdom'}, {'@type': 'Country', 'name': 'United States'}])
    elif kind == 'guide':
        entity.update(headline=h1, datePublished=DATE, dateModified=DATE, author={'@type': 'Person', 'name': 'Hasnain Qureshi', 'url': BASE + '/'}, image=BASE + '/asset/portfolio-social.jpg')
    elif kind == 'tool':
        entity.update(applicationCategory='BusinessApplication', operatingSystem='Any', browserRequirements='JavaScript required', offers={'@type': 'Offer', 'price': '0', 'priceCurrency': 'USD'})
    graph = {'@context': 'https://schema.org', '@graph': [
        {'@type': 'WebPage', '@id': url + '#webpage', 'url': url, 'name': title, 'description': description, 'inLanguage': 'en', 'dateModified': DATE, 'isPartOf': {'@id': BASE + '/#website'}, 'mainEntity': {'@id': url + '#entity'}, 'breadcrumb': {'@id': url + '#breadcrumb'}}, entity,
        {'@type': 'BreadcrumbList', '@id': url + '#breadcrumb', 'itemListElement': [
            {'@type': 'ListItem', 'position': 1, 'name': 'Portfolio', 'item': BASE + '/'},
            {'@type': 'ListItem', 'position': 2, 'name': h1, 'item': url}]}]}
    facts_html = '<div class="case-facts">' + ''.join('<span><small>' + label + '</small><strong>' + html.escape(value) + '</strong></span>' for label, value in zip(['Focus', 'Workflow', 'Working together'], facts)) + '</div>' if facts else ''
    byline = f'<p>By <a href="/">Hasnain Qureshi</a> &middot; <time datetime="{DATE}">27 October 2026</time></p>' if kind == 'guide' else ''
    out = f'''<!doctype html>
<html lang="en"><head>
<meta charset="utf-8" /><meta name="viewport" content="width=device-width,initial-scale=1" />
<title>{html.escape(title)}</title><meta name="description" content="{html.escape(description, quote=True)}" />
<meta name="author" content="Hasnain Qureshi" /><meta name="robots" content="index, follow, max-image-preview:large" />
<link rel="canonical" href="{url}" /><link rel="icon" href="/favicon.svg" type="image/svg+xml" /><meta name="theme-color" content="#080c12" />
<meta property="og:type" content="{'article' if kind == 'guide' else 'website'}" /><meta property="og:title" content="{html.escape(title, quote=True)}" /><meta property="og:description" content="{html.escape(description, quote=True)}" /><meta property="og:url" content="{url}" /><meta property="og:image" content="{BASE}/asset/portfolio-social.jpg" /><meta property="og:image:alt" content="Hasnain Qureshi developer portfolio" /><meta name="twitter:card" content="summary_large_image" />
<link rel="preload" href="/fonts/Moderat-Regular.woff2" as="font" type="font/woff2" crossorigin />
<link rel="stylesheet" href="/css/case-study.css" /><link rel="stylesheet" href="/css/service.css" /><link rel="stylesheet" href="/css/portfolio-type-system.css" /><link rel="stylesheet" href="/css/business-tools.css" /><link rel="stylesheet" href="/css/site-layout.css" />
<script type="application/ld+json">{json.dumps(graph, ensure_ascii=False)}</script>
<script src="/js/site-analytics.js" defer></script><script src="/js/site-layout.js" defer></script>
{''.join(f'<script src="{script}" defer></script>' for script in scripts)}
<noscript><style>.shared-navigation{{display:flex;flex-wrap:wrap}}.shared-menu-toggle{{display:none}}</style></noscript>
</head><body class="content-page service-page">
<a class="skip-link" href="#main">Skip to content</a>{header}
<main id="main"><header class="case-hero"><nav class="service-breadcrumb" aria-label="Breadcrumb"><a href="/">Portfolio</a> / <a href="/{'insights' if kind == 'guide' else 'tools' if kind == 'tool' else 'services'}/">{'Insights' if kind == 'guide' else 'Tools' if kind == 'tool' else 'Services'}</a> / <span aria-current="page">{html.escape(h1)}</span></nav>
<p class="eyebrow">{'Engineering guides' if kind == 'guide' else 'Browser tools' if kind == 'tool' else 'Independent development / UK & US teams'}</p><h1>{html.escape(h1)}</h1><p class="case-hero_intro">{intro}</p>{byline}
{'' if kind == 'tool' else '<div class="service-actions"><a href="/#contact">Discuss your project</a><a href="/services/">Explore services</a></div>'}{facts_html}</header>
<div class="case-body">{body}</div></main>
<section class="site-callout"><div class="shared-container"><div><h2>Bring your next workflow into focus.</h2><p>Share the task, the systems involved and the outcome you need. Based in Karachi, working remotely with UK and US teams.</p></div><div class="callout-actions"><a href="/#contact">Discuss your project</a><a href="/services/">Explore services</a></div></div></section>
{footer}{tawk}</body></html>
'''
    target = ROOT / path.strip('/') / 'index.html'
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(out, encoding='utf-8')


def section(title, content, section_id=''):
    attrs = ' id="' + section_id + '"' if section_id else ''
    return f'<section class="case-section"{attrs}><h2>{title}</h2><div class="case-section_copy">{content}</div></section>'


if __name__ == '__main__':
    for item in SERVICES:
        render('/services/' + item['slug'] + '/', item['title'], item['description'], item['name'], item['intro'], ''.join(section(h, b) for h, b in item['sections']), facts=item['facts'])
    print('Rendered', len(SERVICES), 'service pages.')
